26: // Synthetic Go-JSON-shaped responses; only the external HTTP transport is simulated.
27: function responseFor(id: string, content: string) {
28:   return {
29:     chat: {
30:       id,
31:       title: `Conversation ${id}`,
32:       created_at: firstTime,
33:       messages: [
34:         {
35:           role: "assistant",
36:           content,
37:           thinking: "",
38:           stream: false,
39:           created_at: firstTime,
40:           updated_at: secondTime,
41:           thinkingTimeStart: firstTime,
42:           thinkingTimeEnd: secondTime,
43:           attachments: [{ filename: "evidence.txt", data: "cHJlc2VydmU=" }],
44:           tool_calls: [
45:             {
46:               type: "function",
47:               function: {
48:                 name: "lookup",
49:                 arguments: '{"query":"retained"}',
50:                 result: { count: 0, found: false, values: [null, "retained"] },
51:               },
52:             },
53:           ],
54:         },
55:         {
56:           role: "user",
57:           content: `Follow-up ${id}`,
58:           thinking: "",
