76: describe("generated model production consumers", () => {
77:   it("materialises nested chat models through the real API consumer", async () => {
78:     const wire = responseFor("alpha", "Alpha **important**.");
79:     const fetch = vi.fn(async () => new Response(JSON.stringify(wire)));
80:     vi.stubGlobal("fetch", fetch);
81: 
82:     const response = await getChat("alpha");
83:     expect(fetch).toHaveBeenCalledWith(expect.stringContaining("/api/v1/chat/alpha"));
84:     expect(response).toBeInstanceOf(ChatResponse);
85:     expect(response.chat).toBeInstanceOf(Chat);
86:     expect(response.chat.id).toBe("alpha");
87:     expect(response.chat.messages).toHaveLength(2);
88:     const first = response.chat.messages[0];
89:     expect(first).toBeInstanceOf(Message);
90:     expect(first.attachments?.[0]).toBeInstanceOf(File);
91:     expect(first.attachments?.[0].filename).toBe("evidence.txt");
92:     expect(first.tool_calls?.[0]).toBeInstanceOf(ToolCall);
93:     expect(first.tool_calls?.[0].function).toBeInstanceOf(ToolFunction);
94:     expect(first.tool_calls?.[0].function.result).toEqual({
95:       count: 0,
96:       found: false,
97:       values: [null, "retained"],
98:     });
99:     expect(response.chat.messages[1].content).toBe("Follow-up alpha");
100:   });
