102:   it("delivers distinct decoded content to the real Markdown renderer", async () => {
103:     vi.stubGlobal(
104:       "fetch",
105:       vi.fn(async (url: string) =>
106:         new Response(
107:           JSON.stringify(
108:             url.endsWith("/alpha")
109:               ? responseFor("alpha", "Alpha **important**.")
110:               : responseFor("beta", "Beta *different*."),
111:           ),
112:         ),
113:       ),
114:     );
115:     const first = await getChat("alpha");
116:     const second = await getChat("beta");
117:     const render = (response: ChatResponse) =>
118:       renderToStaticMarkup(
119:         <StreamingMarkdownContent content={response.chat.messages[0].content} />,
120:       );
121:     const alpha = render(first);
122:     const beta = render(second);
123:     expect(alpha).toContain("Alpha");
124:     expect(alpha).toMatch(/<span\b[^>]*data-streamdown="strong"[^>]*>important<\/span>/);
125:     expect(alpha).not.toContain("Beta");
126:     expect(beta).toContain("Beta");
127:     expect(beta).toMatch(/<em\b[^>]*>different<\/em>/);
128:     expect(beta).not.toContain("Alpha");
129:   });
